<?php

declare(strict_types=1);

namespace ParticleAcademy\Stripe\Laravel;

use ParticleAcademy\Connectors\ConnectorResult;
use ParticleAcademy\Connectors\Transport;
use PHPUnit\Framework\Assert;

/*
 * GENERATED by weaver from provider/ and its Laravel emitter (src/Laravel/StripeFake.php). Do not edit;
 * a hand-edit is destroyed by the next protocol sync. Fix weaver and regenerate.
 */

/**
 * Stripe::fake(): every call is answered from the connector's FAKER (no request
 * leaves the app) and recorded, as the caller gave it, for the assertions below.
 * The faker is the same one the canvas and the flow executors use, so a test
 * sees the shape a real call returns.
 */
final class StripeFake extends StripeClient
{
    /** @var list<array{operation: string, config: array<string,mixed>, input: mixed}> */
    private array $sent = [];

    public function call(
        string $operation,
        array $config = [],
        mixed $input = null,
        ?string $idempotencyKey = null,
        ?array $credentials = null,
        ?Transport $transport = null,
    ): ConnectorResult {
        $this->sent[] = ['operation' => $operation, 'config' => $config, 'input' => $input];

        return parent::call($operation, ['mode' => 'fake'] + $config, $input, $idempotencyKey, [], null);
    }

    /** @param (callable(array<string,mixed>, mixed): bool)|null $callback */
    public function assertSent(string $operation, ?callable $callback = null): void
    {
        Assert::assertNotEmpty($this->matching($operation, $callback), "Expected {$operation} to be called, and it was not.");
    }

    /** @param (callable(array<string,mixed>, mixed): bool)|null $callback */
    public function assertNotSent(string $operation, ?callable $callback = null): void
    {
        Assert::assertEmpty($this->matching($operation, $callback), "Expected {$operation} not to be called, and it was.");
    }

    public function assertNothingSent(): void
    {
        Assert::assertSame([], $this->sent, 'Expected no calls, and there were '.count($this->sent).'.');
    }

    public function assertSentCount(int $count): void
    {
        Assert::assertCount($count, $this->sent, "Expected {$count} call(s), and there were ".count($this->sent).'.');
    }

    /** @return list<array{operation: string, config: array<string,mixed>, input: mixed}> */
    public function sent(): array
    {
        return $this->sent;
    }

    /** @return list<array{operation: string, config: array<string,mixed>, input: mixed}> */
    private function matching(string $operation, ?callable $callback): array
    {
        return array_values(array_filter(
            $this->sent,
            static fn (array $call): bool => $call['operation'] === $operation
                && ($callback === null || $callback($call['config'], $call['input'])),
        ));
    }
}
